import { PrismaClient } from '@prisma/client';

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient };
export const prisma = globalForPrisma.prisma || new PrismaClient();
if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;

implementation_code_templates.api_bookings_route_ts:
import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { sendBrevoLeadAlert } from '@/lib/brevo';

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { customerName, phoneNumber, categoryId, selectedSubService, gorakhpurArea, fullAddress } = body;

    if (!customerName || !phoneNumber || !categoryId || !selectedSubService || !gorakhpurArea) {
      return NextResponse.json({ success: false, error: 'Missing required fields' }, { status: 400 });
    }

    const bookingId = `GKP-${Math.floor(1000 + Math.random() * 9000)}`;

    const booking = await prisma.booking.create({
      data: {
        bookingId,
        customerName,
        phoneNumber,
        categoryId,
        selectedSubService,
        gorakhpurArea,
        fullAddress: fullAddress || null,
        inspectionFee: 99,
        feeStatus: 'Pay After Service',
        bookingStatus: 'Request Confirmed'
      }
    });

    // Asynchronous lead alert via Brevo (Non-blocking)
    sendBrevoLeadAlert(booking).catch(err => console.error('Brevo notification error:', err));

    return NextResponse.json({ success: true, bookingId: booking.bookingId, redirectUrl: `/thank-you?booking_id=${booking.bookingId}` }, { status: 201 });
  } catch (error) {
    console.error('Booking creation error:', error);
    return NextResponse.json({ success: false, error: 'Internal Server Error' }, { status: 500 });
  }
}

implementation_code_templates.lib_brevo_ts:
export async function sendBrevoLeadAlert(booking: any) {
  const apiKey = process.env.BREVO_API_KEY;
  const adminEmail = process.env.ADMIN_NOTIFICATION_EMAIL;
  if (!apiKey || !adminEmail) return;

  const emailPayload = {
    sender: { name: 'Gorakhpur Repairs Alert', email: 'notifications@gorakhpurrepairs.com' },
    to: [{ email: adminEmail }],
    subject: `🚨 New Lead #${booking.bookingId}: ${booking.selectedSubService} - ${booking.gorakhpurArea}`,
    htmlContent: `<h2>New Service Request Received</h2><p><strong>Booking ID:</strong> ${booking.bookingId}</p><p><strong>Customer:</strong> ${booking.customerName}</p><p><strong>Mobile:</strong> <a href="tel:${booking.phoneNumber}">${booking.phoneNumber}</a></p><p><strong>Service:</strong> ${booking.selectedSubService}</p><p><strong>Area:</strong> ${booking.gorakhpurArea}</p><p><strong>Inspection Fee:</strong> ₹99 (Pay after service)</p><p><em>Call the customer within 10 minutes.</em></p>`
  };

  await fetch('https://api.brevo.com/v3/smtp/email', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'api-key': apiKey },
    body: JSON.stringify(emailPayload)
  });
}
